    def can_dispatch_effect(self, effect_id: str) -> bool:
        effect = self.get_effect(effect_id)
        return effect.state == EffectState.PREPARING.value

    def mark_effect_dispatched(self, effect_id: str) -> EffectRecord:
        return self._transition_effect(
            effect_id,
            allowed={EffectState.PREPARING.value},
            target=EffectState.DISPATCHED.value,
            operation_state=OperationState.DISPATCHED.value,
        )

    def mark_effect_reconcile_required(
        self,
        effect_id: str,
        *,
        evidence: dict[str, Any] | None = None,
    ) -> EffectRecord:
        return self._transition_effect(
            effect_id,
            allowed={EffectState.PREPARING.value, EffectState.DISPATCHED.value, EffectState.CONFIRMING.value},
            target=EffectState.RECONCILE_REQUIRED.value,
            operation_state=OperationState.RECONCILE_REQUIRED.value,
            evidence=evidence,
        )

    def mark_effect_succeeded(
        self,
        effect_id: str,
        *,
        remote_id: str | None = None,
        evidence: dict[str, Any] | None = None,
    ) -> EffectRecord:
        return self._transition_effect(
            effect_id,
            allowed={
                EffectState.DISPATCHED.value,
                EffectState.CONFIRMING.value,
                EffectState.RECONCILE_REQUIRED.value,
            },
            target=EffectState.SUCCEEDED.value,
            operation_state=OperationState.CONFIRMING.value,
            remote_id=remote_id,
            evidence=evidence,
        )

    def mark_effect_observed_existing_succeeded(
        self,
        effect_id: str,
        *,
        remote_id: str,
        evidence: dict[str, Any] | None = None,
    ) -> EffectRecord:
        """Record an exact remote effect that pre-dates the current dispatch boundary.

        This transition is deliberately PREPARING -> SUCCEEDED and is only for
        independently corroborated pre-existing remote state. It must never be
        used after a current-run dispatch.
        """
        merged = dict(evidence or {})
        merged.update({
            "reconciled_existing": True,
            "no_current_dispatch": True,
        })
        return self._transition_effect(
            effect_id,
            allowed={EffectState.PREPARING.value},
            target=EffectState.SUCCEEDED.value,
            operation_state=OperationState.CONFIRMING.value,
            remote_id=remote_id,
            evidence=merged,
        )

    def mark_effect_failed_known(
        self,
        effect_id: str,
        *,
        evidence: dict[str, Any] | None = None,
    ) -> EffectRecord:
        self._initialize()

    def _connect(self) -> sqlite3.Connection:
        connection = sqlite3.connect(self.path, timeout=30, isolation_level=None)
        connection.row_factory = sqlite3.Row
        connection.execute("PRAGMA foreign_keys = ON")
        connection.execute("PRAGMA journal_mode = WAL")
        connection.execute("PRAGMA synchronous = FULL")
        return connection

    @contextmanager
    def _transaction(self) -> Iterator[sqlite3.Connection]:
        connection = self._connect()
        try:
            connection.execute("BEGIN IMMEDIATE")
            yield connection
            connection.execute("COMMIT")
        except Exception:
            if connection.in_transaction:
                connection.execute("ROLLBACK")
            raise
        finally:
            connection.close()

    @contextmanager
